examples.template:
MonarchAiSuggestedActions(
    [
        MonarchAiSuggestedAction(
            id: {{actions.0.id}},
            label: {{actions.0.label}},
            description: {{actions.0.description}}
        ),
        MonarchAiSuggestedAction(
            id: {{actions.1.id}},
            label: {{actions.1.label}},
            risk: {{actions.1.risk|case}}
        ),
        MonarchAiSuggestedAction(
            id: {{actions.2.id}},
            label: {{actions.2.label}},
            description: {{actions.2.description}},
            requiresApproval: {{actions.2.requiresApproval}},
            consequences: [{{actions.2.consequences.0}}, {{actions.2.consequences.1}}],
            confirmLabel: {{actions.2.confirmLabel}}
        ),
        MonarchAiSuggestedAction(
            id: {{actions.3.id}},
            label: {{actions.3.label}},
            description: {{actions.3.description}},
            risk: {{actions.3.risk|case}},
            consequences: [{{actions.3.consequences.0}}, {{actions.3.consequences.1}}],
            confirmLabel: {{actions.3.confirmLabel}}
        ),
    ],
    onDismiss: { _ in },
    onRun: { _ in }
)

examples.code:
MonarchAiSuggestedActions(
    [MonarchAiSuggestedAction(id: "call", label: "Call the customer back", status: .done)],
    title: "Next steps",
    origin: .rule
) { _ in }
